package http

import (
	"encoding/json"
	nethttp "net/http"
)

func healthHandler(
	w nethttp.ResponseWriter,
	r *nethttp.Request,
) {
	w.Header().Set("Content-Type", "application/json")

	json.NewEncoder(w).Encode(map[string]string{
		"status": "ok",
	})
}

